'use client';

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import {
  Product,
  Category,
  HeroBanner,
  PromoBanner,
  Announcement,
  Coupon,
  OfferCampaign,
  StoreSettings,
  Review,
} from '@/types';
import { DataStore } from '@/lib/store/data-store';
import { INITIAL_SETTINGS } from '@/lib/data/initial-data';
import { supabase, isSupabaseConfigured } from '@/lib/supabase/client';

interface StoreContextType {
  products: Product[];
  categories: Category[];
  heroBanners: HeroBanner[];
  promoBanners: PromoBanner[];
  announcement: Announcement;
  settings: StoreSettings;
  coupons: Coupon[];
  offers: OfferCampaign[];
  refreshData: () => void;
  getProductBySlug: (slug: string) => Product | undefined;
  getProductById: (id: string) => Product | undefined;
  getReviewsForProduct: (productId: string) => Review[];
  submitReview: (data: {
    productId: string;
    userId?: string;
    userName: string;
    rating: number;
    title: string;
    comment: string;
    images?: string[];
  }) => { success: boolean; message: string };
  subscribeRestock: (productId: string, email: string, phone?: string, variantId?: string) => { success: boolean; message: string };
  subscribeNewsletter: (email: string) => { success: boolean; message: string };
  submitContactForm: (data: { name: string; email: string; phone?: string; subject: string; message: string }) => {
    success: boolean;
    message: string;
  };
  isLiveChatOpen: boolean;
  toggleLiveChat: () => void;
  closeLiveChat: () => void;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export function StoreProvider({ children }: { children: React.ReactNode }) {
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [heroBanners, setHeroBanners] = useState<HeroBanner[]>([]);
  const [promoBanners, setPromoBanners] = useState<PromoBanner[]>([]);
  const [announcement, setAnnouncement] = useState<Announcement>(DataStore.getAnnouncement());
  const [settings, setSettings] = useState<StoreSettings>(INITIAL_SETTINGS);
  const [coupons, setCoupons] = useState<Coupon[]>([]);
  const [offers, setOffers] = useState<OfferCampaign[]>([]);
  const [isLiveChatOpen, setIsLiveChatOpen] = useState(false);

  const refreshData = useCallback(() => {
    setProducts(DataStore.getProducts());
    setCategories(DataStore.getCategories());
    setHeroBanners(DataStore.getHeroBanners());
    setPromoBanners(DataStore.getPromoBanners());
    setAnnouncement(DataStore.getAnnouncement());
    setSettings(DataStore.getSettings());
    setCoupons(DataStore.getCoupons());
    setOffers(DataStore.getOffers());
  }, []);

  useEffect(() => {
    refreshData();

    // 1. Listen for local DataStore changes across tabs and within same window
    const handleDataChange = () => {
      refreshData();
    };

    if (typeof window !== 'undefined') {
      window.addEventListener('ozeira_datastore_change', handleDataChange);
      window.addEventListener('storage', handleDataChange);
    }

    // 2. Initial hydration from Supabase
    DataStore.syncFromSupabase().then(() => {
      refreshData();
    });

    // 3. Realtime subscription to live postgres changes
    if (isSupabaseConfigured) {
      const channel = supabase
        .channel('ozeira-store-realtime')
        .on('postgres_changes', { event: '*', schema: 'public' }, () => {
          DataStore.syncFromSupabase().then(() => {
            refreshData();
          });
        })
        .subscribe();

      return () => {
        if (typeof window !== 'undefined') {
          window.removeEventListener('ozeira_datastore_change', handleDataChange);
          window.removeEventListener('storage', handleDataChange);
        }
        supabase.removeChannel(channel);
      };
    }

    return () => {
      if (typeof window !== 'undefined') {
        window.removeEventListener('ozeira_datastore_change', handleDataChange);
        window.removeEventListener('storage', handleDataChange);
      }
    };
  }, [refreshData]);

  const getProductBySlug = (slug: string) => products.find((p) => p.slug === slug);
  const getProductById = (id: string) => products.find((p) => p.id === id);
  const getReviewsForProduct = (productId: string) => DataStore.getReviews(productId);

  const submitReview = (data: {
    productId: string;
    userId?: string;
    userName: string;
    rating: number;
    title: string;
    comment: string;
    images?: string[];
  }) => {
    DataStore.addReview({
      product_id: data.productId,
      user_id: data.userId,
      user_name: data.userName,
      rating: data.rating,
      title: data.title,
      comment: data.comment,
      images: data.images || [],
      is_verified_purchase: true,
    });
    refreshData();
    return {
      success: true,
      message: 'Thank you for your review! 100 loyalty points have been credited to your account.',
    };
  };

  const subscribeRestock = (productId: string, email: string, phone?: string, variantId?: string) => {
    DataStore.addRestockRequest({
      productId,
      variantId,
      email,
      phone,
    });
    return {
      success: true,
      message: "You're all set! We'll notify you via email and SMS the moment this piece is back in stock.",
    };
  };

  const subscribeNewsletter = (email: string) => {
    const ok = DataStore.addSubscriber(email);
    if (ok) {
      return {
        success: true,
        message: 'Welcome to the Ozeira circle! Use code LUXE10 for 10% off your next order.',
      };
    }
    return {
      success: false,
      message: 'This email is already subscribed to Ozeira private announcements.',
    };
  };

  const submitContactForm = (data: { name: string; email: string; phone?: string; subject: string; message: string }) => {
    DataStore.addContactMessage(data);
    return {
      success: true,
      message: 'Your message has been received by our concierge team. We will reply within 24 hours.',
    };
  };

  const toggleLiveChat = () => setIsLiveChatOpen((prev) => !prev);
  const closeLiveChat = () => setIsLiveChatOpen(false);

  return (
    <StoreContext.Provider
      value={{
        products,
        categories,
        heroBanners,
        promoBanners,
        announcement,
        settings,
        coupons,
        offers,
        refreshData,
        getProductBySlug,
        getProductById,
        getReviewsForProduct,
        submitReview,
        subscribeRestock,
        subscribeNewsletter,
        submitContactForm,
        isLiveChatOpen,
        toggleLiveChat,
        closeLiveChat,
      }}
    >
      {children}
    </StoreContext.Provider>
  );
}

export function useStore() {
  const context = useContext(StoreContext);
  if (!context) {
    throw new Error('useStore must be used within a StoreProvider');
  }
  return context;
}

'use client';

import React, { createContext, useContext, useState, useEffect } from 'react';

type Theme = 'light' | 'dark' | 'system';

interface ThemeContextType {
  theme: Theme;
  resolvedTheme: 'light' | 'dark';
  setTheme: (theme: Theme) => void;
  toggleTheme: () => void;
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

const THEME_KEY = 'ozeira_theme_v1';

export function ThemeProvider({ children }: { children: React.ReactNode }) {
  const [theme, setThemeState] = useState<Theme>('light');
  const [resolvedTheme, setResolvedTheme] = useState<'light' | 'dark'>('light');
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
    const saved = localStorage.getItem(THEME_KEY) as Theme | null;
    if (saved) {
      setThemeState(saved);
    }
  }, []);

  useEffect(() => {
    if (!mounted) return;

    let resolved: 'light' | 'dark' = 'light';
    if (theme === 'system') {
      resolved = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    } else {
      resolved = theme;
    }

    setResolvedTheme(resolved);
    document.documentElement.classList.toggle('dark', resolved === 'dark');
    localStorage.setItem(THEME_KEY, theme);
  }, [theme, mounted]);

  // Listen for system theme changes
  useEffect(() => {
    if (theme !== 'system') return;
    const mq = window.matchMedia('(prefers-color-scheme: dark)');
    const handler = (e: MediaQueryListEvent) => {
      setResolvedTheme(e.matches ? 'dark' : 'light');
      document.documentElement.classList.toggle('dark', e.matches);
    };
    mq.addEventListener('change', handler);
    return () => mq.removeEventListener('change', handler);
  }, [theme]);

  const setTheme = (t: Theme) => setThemeState(t);

  const toggleTheme = () => {
    setThemeState((prev) => {
      if (prev === 'light') return 'dark';
      if (prev === 'dark') return 'light';
      return 'light';
    });
  };

  return (
    <ThemeContext.Provider value={{ theme, resolvedTheme, setTheme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme() {
  const ctx = useContext(ThemeContext);
  if (!ctx) throw new Error('useTheme must be used within ThemeProvider');
  return ctx;
}

'use client';

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Product } from '@/types';
import { DataStore } from '@/lib/store/data-store';

interface WishlistContextType {
  wishlistIds: string[];
  wishlistProducts: Product[];
  toggleWishlist: (productId: string) => void;
  isInWishlist: (productId: string) => boolean;
  clearWishlist: () => void;
  count: number;
}

const WishlistContext = createContext<WishlistContextType | undefined>(undefined);

const WISHLIST_KEY = 'ozeira_wishlist_v1';

export function WishlistProvider({ children }: { children: React.ReactNode }) {
  const [wishlistIds, setWishlistIds] = useState<string[]>([]);
  const [products, setProducts] = useState<Product[]>([]);

  useEffect(() => {
    try {
      const stored = localStorage.getItem(WISHLIST_KEY);
      if (stored) {
        setWishlistIds(JSON.parse(stored));
      } else {
        // Initial sample items
        setWishlistIds(['prod-1', 'prod-3']);
      }
      setProducts(DataStore.getProducts());
    } catch (e) {
      console.error('Failed to load wishlist', e);
    }
  }, []);

  const toggleWishlist = (productId: string) => {
    setWishlistIds((prev) => {
      let updated: string[];
      if (prev.includes(productId)) {
        updated = prev.filter((id) => id !== productId);
      } else {
        updated = [...prev, productId];
      }
      try {
        localStorage.setItem(WISHLIST_KEY, JSON.stringify(updated));
      } catch (e) {
        console.error('Error saving wishlist', e);
      }
      return updated;
    });
  };

  const isInWishlist = (productId: string) => wishlistIds.includes(productId);

  const clearWishlist = () => {
    setWishlistIds([]);
    localStorage.removeItem(WISHLIST_KEY);
  };

  const wishlistProducts = products.filter((p) => wishlistIds.includes(p.id));

  return (
    <WishlistContext.Provider
      value={{
        wishlistIds,
        wishlistProducts,
        toggleWishlist,
        isInWishlist,
        clearWishlist,
        count: wishlistIds.length,
      }}
    >
      {children}
    </WishlistContext.Provider>
  );
}

export function useWishlist() {
  const context = useContext(WishlistContext);
  if (!context) {
    throw new Error('useWishlist must be used within a WishlistProvider');
  }
  return context;
}

'use client';

import { supabase } from '@/lib/supabase/client';
import { CartItem } from '@/types';
import { DataStore } from '@/lib/store/data-store';
import { NotificationService } from './notification-service';

export interface AbandonedCartRecord {
  id: string;
  user_id?: string;
  email: string;
  phone?: string;
  cart_items: CartItem[];
  total_amount: number;
  recovery_token: string;
  reminders_sent: number;
  last_reminder_at?: string;
  is_recovered: boolean;
  created_at: string;
  updated_at: string;
}

const STORAGE_KEY = 'ozeira_abandoned_carts_v1';

export const AbandonedCartService = {
  // Save or update an abandoned cart checkpoint
  async recordCartSession(
    email: string,
    cartItems: CartItem[],
    phone?: string,
    userId?: string
  ): Promise<string | null> {
    if (!email || !cartItems || cartItems.length === 0) return null;

    const settings = DataStore.getSettings();
    if (!settings.abandonedCart?.isEnabled) return null;

    const totalAmount = cartItems.reduce(
      (sum, item) =>
        sum +
        ((item.product.sale_price ?? item.product.base_price) + (item.variant?.additional_price || 0)) *
          item.quantity,
      0
    );

    const token = 'rec_' + Math.random().toString(36).substring(2, 10) + Date.now().toString(36);
    const cartId = 'ac-' + Date.now();

    const record: AbandonedCartRecord = {
      id: cartId,
      user_id: userId,
      email: email.trim().toLowerCase(),
      phone: phone?.trim(),
      cart_items: cartItems,
      total_amount: totalAmount,
      recovery_token: token,
      reminders_sent: 0,
      is_recovered: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    };

    // Save locally
    try {
      const existing: AbandonedCartRecord[] = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
      const filtered = existing.filter((c) => c.email !== record.email || c.is_recovered);
      filtered.push(record);
      localStorage.setItem(STORAGE_KEY, JSON.stringify(filtered));
    } catch (e) {
      // LocalStorage fallback
    }

    // Save to Supabase
    try {
      await supabase.from('abandoned_carts').upsert({
        id: record.id,
        user_id: record.user_id,
        email: record.email,
        phone: record.phone,
        cart_items: record.cart_items,
        total_amount: record.total_amount,
        recovery_token: record.recovery_token,
        reminders_sent: 0,
        is_recovered: false,
        updated_at: new Date().toISOString(),
      });
    } catch (err) {
      console.warn('[AbandonedCart] Supabase save error:', err);
    }

    return token;
  },

  // Mark cart as recovered / completed when order is placed
  async markCartRecovered(email: string) {
    if (!email) return;
    const cleanEmail = email.trim().toLowerCase();

    try {
      const existing: AbandonedCartRecord[] = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
      const updated = existing.map((c) => (c.email === cleanEmail ? { ...c, is_recovered: true } : c));
      localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
    } catch (e) {}

    try {
      await supabase
        .from('abandoned_carts')
        .update({ is_recovered: true, updated_at: new Date().toISOString() })
        .eq('email', cleanEmail);
    } catch (err) {
      console.warn('[AbandonedCart] Supabase mark recovered error:', err);
    }
  },

  // Get cart items from recovery token
  async getCartByToken(token: string): Promise<AbandonedCartRecord | null> {
    if (!token) return null;

    try {
      const { data, error } = await supabase
        .from('abandoned_carts')
        .select('*')
        .eq('recovery_token', token)
        .single();

      if (data && !error) return data as AbandonedCartRecord;
    } catch (err) {}

    // Fallback to local storage
    try {
      const existing: AbandonedCartRecord[] = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
      return existing.find((c) => c.recovery_token === token) || null;
    } catch (e) {
      return null;
    }
  },

  // Send Abandoned Cart Reminder Email (Max 2 reminders, no spam)
  async dispatchReminder(cart: AbandonedCartRecord, reminderNumber: 1 | 2) {
    if (cart.is_recovered || cart.reminders_sent >= (DataStore.getSettings().abandonedCart?.maxReminders || 2)) {
      return false;
    }

    const settings = DataStore.getSettings();
    const couponCode = settings.abandonedCart?.reminderCouponCode || 'WELCOME10';
    const recoveryUrl = `${typeof window !== 'undefined' ? window.location.origin : 'http://localhost:3000'}/checkout?recover_token=${cart.recovery_token}&coupon=${couponCode}`;

    const itemsHtml = cart.cart_items
      .map(
        (i) => {
          const unitPrice = (i.product.sale_price ?? i.product.base_price) + (i.variant?.additional_price || 0);
          return `
      <div style="display:flex;align-items:center;gap:12px;padding:8px 0;border-bottom:1px solid #f0eae1;">
        <img src="${i.product.images[0]?.image_url || ''}" width="50" height="50" style="border-radius:8px;object-fit:cover;" />
        <div style="flex:1;">
          <strong style="color:#1a1714;font-size:13px;">${i.product.title}</strong>
          <div style="font-size:12px;color:#786f66;">Qty: ${i.quantity} • ₹${unitPrice.toLocaleString('en-IN')}</div>
        </div>
      </div>
    `;
        }
      )
      .join('');

    const subject = reminderNumber === 1 
      ? (settings.abandonedCart?.emailSubject || 'Your curated pieces are waiting at Ozeira')
      : `Exclusive Invitation: Complete your order with 10% privilege discount [${couponCode}]`;

    const htmlContent = `
      <div style="font-family:'Playfair Display',Georgia,serif;max-width:600px;margin:0 auto;background:#fdfbf9;padding:32px;border:1px solid #e8e0d5;border-radius:16px;">
        <div style="text-align:center;margin-bottom:24px;">
          <h1 style="letter-spacing:4px;color:#1a1714;margin:0;font-size:24px;">O Z E I R A</h1>
          <p style="font-size:11px;letter-spacing:2px;color:#c46331;text-transform:uppercase;margin-top:4px;">Atelier Concierge</p>
        </div>
        <p style="color:#1a1714;font-size:15px;line-height:1.6;">
          ${reminderNumber === 1 ? 'We noticed you left some exquisite handcrafted pieces in your selection bag.' : 'Your reserved pieces remain held in our atelier. As a special courtesy, enjoy an exclusive privilege discount on us.'}
        </p>
        <div style="background:#ffffff;padding:16px;border-radius:12px;border:1px solid #f0eae1;margin:20px 0;">
          <h4 style="margin:0 0 12px;font-size:13px;color:#786f66;text-transform:uppercase;letter-spacing:1px;">Your Selected Atelier Pieces</h4>
          ${itemsHtml}
          <div style="text-align:right;margin-top:12px;font-size:14px;font-weight:bold;color:#1a1714;">
            Total: ₹${cart.total_amount.toLocaleString('en-IN')}
          </div>
        </div>
        ${couponCode ? `
          <div style="text-align:center;background:#fdf6f0;border:1px dashed #c46331;padding:12px;border-radius:8px;margin-bottom:20px;">
            <span style="font-size:12px;color:#786f66;">Use Code at Checkout:</span>
            <span style="display:block;font-size:16px;font-weight:bold;color:#c46331;letter-spacing:2px;">${couponCode}</span>
          </div>
        ` : ''}
        <div style="text-align:center;margin-top:28px;">
          <a href="${recoveryUrl}" style="background:#1a1714;color:#ffffff;padding:14px 28px;text-decoration:none;border-radius:8px;font-size:13px;font-weight:bold;letter-spacing:1px;display:inline-block;">
            COMPLETE YOUR ORDER &rarr;
          </a>
        </div>
      </div>
    `;

    // Log notification
    await NotificationService.sendNotification({
      type: 'email',
      recipient: cart.email,
      subject: subject,
      message: `Your Ozeira bag with ${cart.cart_items.length} items is waiting. Complete order: ${recoveryUrl}`,
      metadata: { abandoned_cart_id: cart.id, recovery_token: cart.recovery_token, reminderNumber },
    });

    // Update reminder count
    const updatedCount = cart.reminders_sent + 1;
    try {
      await supabase
        .from('abandoned_carts')
        .update({
          reminders_sent: updatedCount,
          last_reminder_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        })
        .eq('id', cart.id);
    } catch (e) {}

    return true;
  },
};

'use client';

declare global {
  interface Window {
    gtag?: (...args: any[]) => void;
    dataLayer?: any[];
    fbq?: (...args: any[]) => void;
    _fbq?: any;
  }
}

export const AnalyticsService = {
  // Safe track event
  trackEvent(eventName: string, params: Record<string, any> = {}) {
    if (typeof window === 'undefined') return;

    try {
      // Google Analytics 4
      if (typeof window.gtag === 'function') {
        window.gtag('event', eventName, params);
      }

      // Meta (Facebook) Pixel
      if (typeof window.fbq === 'function') {
        // Map standard GA4 events to Meta Pixel equivalents
        const metaEventMap: Record<string, string> = {
          page_view: 'PageView',
          view_item: 'ViewContent',
          add_to_cart: 'AddToCart',
          begin_checkout: 'InitiateCheckout',
          purchase: 'Purchase',
          search: 'Search',
          add_to_wishlist: 'AddToWishlist',
        };

        const metaEvent = metaEventMap[eventName] || 'CustomEvent';
        if (metaEvent === 'CustomEvent') {
          window.fbq('trackCustom', eventName, params);
        } else {
          window.fbq('track', metaEvent, {
            content_name: params.item_name || params.content_name,
            content_ids: params.items?.map((i: any) => i.item_id) || (params.content_id ? [params.content_id] : []),
            value: params.value,
            currency: params.currency || 'INR',
            num_items: params.items?.length || 1,
          });
        }
      }
    } catch (err) {
      console.warn('[Analytics] Tracker error (safe ignored):', err);
    }
  },

  trackPageView(url: string, title?: string) {
    this.trackEvent('page_view', {
      page_location: url,
      page_title: title || (typeof document !== 'undefined' ? document.title : ''),
    });
  },

  trackViewItem(item: { id: string; name: string; price: number; category?: string }) {
    this.trackEvent('view_item', {
      currency: 'INR',
      value: item.price,
      items: [
        {
          item_id: item.id,
          item_name: item.name,
          item_category: item.category,
          price: item.price,
          quantity: 1,
        },
      ],
    });
  },

  trackAddToCart(item: { id: string; name: string; price: number; quantity: number; category?: string }) {
    this.trackEvent('add_to_cart', {
      currency: 'INR',
      value: item.price * item.quantity,
      items: [
        {
          item_id: item.id,
          item_name: item.name,
          item_category: item.category,
          price: item.price,
          quantity: item.quantity,
        },
      ],
    });
  },

  trackBeginCheckout(items: Array<{ id: string; name: string; price: number; quantity: number }>, totalValue: number) {
    this.trackEvent('begin_checkout', {
      currency: 'INR',
      value: totalValue,
      items: items.map((i) => ({
        item_id: i.id,
        item_name: i.name,
        price: i.price,
        quantity: i.quantity,
      })),
    });
  },

  trackPurchase(order: { id: string; orderNumber: string; totalAmount: number; items: any[] }) {
    this.trackEvent('purchase', {
      transaction_id: order.orderNumber || order.id,
      value: order.totalAmount,
      currency: 'INR',
      items: order.items.map((i: any) => ({
        item_id: i.product_id || i.id,
        item_name: i.product_title || i.name,
        price: i.unit_price || i.price,
        quantity: i.quantity,
      })),
    });
  },
};

import { 
  SupplierCredentials, 
  SupplierCatalogItem, 
  SupplierFulfillmentOrder, 
  SupplierPricingRule 
} from '@/types/supplier';

const CJ_API_BASE_URL = 'https://developers.cjdropshipping.com/api2.0/v1';

export class CJApiClient {
  /**
   * Helper to calculate converted INR cost and suggested luxury selling price
   */
  static computePrices(
    costUSD: number, 
    rule?: SupplierPricingRule
  ): { costINR: number; retailINR: number; marginPercent: number } {
    const exchangeRate = rule?.exchangeRateToINR ?? 87.5;
    const costINR = Math.round(costUSD * exchangeRate);

    let retailINR = costINR;
    const markupType = rule?.markupType ?? 'percentage';
    const markupValue = rule?.markupValue ?? 60; // default 60% markup

    if (markupType === 'percentage') {
      retailINR = Math.round(costINR * (1 + markupValue / 100));
    } else if (markupType === 'fixed') {
      retailINR = costINR + markupValue;
    } else if (markupType === 'multiplier') {
      retailINR = Math.round(costINR * markupValue);
    }

    // Apply ending round (e.g. 999 or 499)
    const ending = rule?.roundToEnding ?? 999;
    if (ending > 0 && ending < 1000) {
      const base = Math.floor(retailINR / 1000) * 1000;
      retailINR = base + ending;
      if (retailINR < costINR * 1.2) {
        retailINR += 1000;
      }
    }

    const marginPercent = retailINR > 0 ? Math.round(((retailINR - costINR) / retailINR) * 100) : 0;
    return { costINR, retailINR, marginPercent };
  }

